<script setup lang="ts">
import { computed, ref } from 'vue'
import { Dumbbell } from '@lucide/vue'
import { useAppStore } from '@/stores/app'
const store=useAppStore();const mode=ref<'login'|'register'>('login');const name=ref('Alex');const email=ref('alex@example.com');const password=ref('workout123');const error=ref('');const title=computed(()=>mode.value==='login'?'Ready when you are.':'Start training clearly.')
function submit(){error.value=password.value.length<8?'Use at least 8 characters.':!email.value.includes('@')?'Enter a valid email.':'';if(error.value)return;mode.value==='login'?store.login(name.value,email.value):store.register(name.value,email.value)}
</script>
<template><main class="auth-page"><section class="auth-copy"><div class="brand"><span class="brand-mark"><Dumbbell :size="20"/></span><span>FORM</span></div><div><span class="eyebrow">YOUR TRAINING, CLEARLY</span><h1>Think less.<br><em>Lift more.</em></h1><p>A focused workout log built to disappear between you and your next set.</p></div><div class="auth-proof"><strong>Fast by design.</strong><span>Routines, history and progress - without the noise.</span></div></section><section class="auth-panel"><form class="auth-card" @submit.prevent="submit"><span class="eyebrow">{{ mode==='login'?'WELCOME BACK':'CREATE ACCOUNT' }}</span><h2>{{ title }}</h2><p>{{ mode==='login'?'Your training data is ready.':'A private training space in under a minute.' }}</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><label>Display name<input v-model="name" autocomplete="name" required maxlength="50"/></label><label>Email<input v-model="email" type="email" autocomplete="email" required/></label><label>Password<input v-model="password" type="password" :autocomplete="mode==='login'?'current-password':'new-password'" required minlength="8"/></label><button class="btn btn-primary btn-wide" type="submit">{{ mode==='login'?'Sign in':'Create account' }}</button><button class="auth-switch" type="button" @click="mode=mode==='login'?'register':'login'">{{ mode==='login'?'New here? Create an account':'Already have an account? Sign in' }}</button><small class="form-note">Private by default - Your data stays yours</small></form></section></main></template>
